begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select ok(relrowsecurity,'Deletion receipts have RLS') from pg_class where oid='account_private.deletions'::regclass;
select ok(not has_table_privilege(r,'account_private.deletions','select'),r||' cannot read deletion receipts') from unnest(array['anon','authenticated','service_role']) r;
select ok(not has_function_privilege(r,'public.begin_my_account_deletion(uuid,text,text)','execute'),r||' cannot impersonate student confirmation') from unnest(array['anon','service_role']) r;
select ok(not has_function_privilege(r,f,'execute'),r||' cannot invoke worker endpoint '||f)
from unnest(array['anon','authenticated']) r cross join unnest(array['public.claim_account_deletion(uuid,text)','public.account_deletion_assets(uuid,uuid)','public.finish_account_deletion(uuid,uuid)']) f;
select ok(not prosecdef and proconfig @> array['search_path=""'],'Public deletion wrapper is invoker with fixed search path')
from pg_proc where oid='public.begin_my_account_deletion(uuid,text,text)'::regprocedure;
select ok(not has_column_privilege('authenticated','public.profiles','deleted_at','update'),'Student cannot edit deletion marker');
insert into auth.users(id,email,email_confirmed_at) values('de1e7200-0000-4000-8000-000000000001','deletion-cleanup-fixture@tests.local',now());
update public.profiles set display_name='Personal name',major='Personal major' where id='de1e7200-0000-4000-8000-000000000001';
insert into auth.sessions(id,user_id,created_at,updated_at) values('de1e7200-0000-4000-8000-000000000101','de1e7200-0000-4000-8000-000000000001',now(),now());
select set_config('request.jwt.claim.sub','de1e7200-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"de1e7200-0000-4000-8000-000000000001","role":"authenticated","session_id":"de1e7200-0000-4000-8000-000000000101"}',true);
set local role authenticated;
select is(public.begin_my_account_deletion('de1e7200-0000-4000-8000-000000000201',repeat('a',64),'DELETE')->>'accepted','true','Live caller confirms their deletion');
select is(public.begin_my_account_deletion('de1e7200-0000-4000-8000-000000000201',repeat('a',64),'DELETE')->>'accepted','true','Same receipt safely retries after session revocation');
select throws_ok($$select public.begin_my_account_deletion('de1e7200-0000-4000-8000-000000000202',repeat('b',64),'DELETE')$$,'42501',null,'A different receipt cannot replace the accepted operation');
select is((select count(*) from public.profiles),0::bigint,'Deleted JWT cannot read profiles');
reset role;
select is((select display_name from public.profiles where id='de1e7200-0000-4000-8000-000000000001'),'Deleted student','Retained identity has neutral label');
select ok((select major is null and avatar_path is null and onboarding_completed_at is null and not is_discoverable and deleted_at is not null from public.profiles where id='de1e7200-0000-4000-8000-000000000001'),'Profile fields cleared and discovery disabled');
select is((select count(*) from auth.sessions where user_id='de1e7200-0000-4000-8000-000000000001'),0::bigint,'All Auth sessions revoked');
select is((select balance from public.points_wallets where profile_id='de1e7200-0000-4000-8000-000000000001'),0::bigint,'Old wallet cleared after retaining its balance');
select is((select count(*) from public.points_ledger where profile_id='de1e7200-0000-4000-8000-000000000001'),0::bigint,'Own point history removed');
select ok(exists(select 1 from points_private.starter_grant_claims where email_fingerprint=points_private.email_fingerprint('deletion-cleanup-fixture@tests.local')),'Welcome claim survives deletion');
select set_config('request.jwt.claim.sub','',true);select set_config('request.jwt.claims','{}',true);
select throws_ok($$select safety_private.assign_staff_role('de1e7200-0000-4000-8000-000000000001','admin',true,'Must not revive deleted account')$$,'23514',null,'Owner tools cannot enable a deleted identity');
set local role service_role;
select is(public.claim_account_deletion('de1e7200-0000-4000-8000-000000000201',repeat('b',64))->>'status','unconfirmed','Wrong secret reveals no deletion');
select is(public.claim_account_deletion('de1e7200-0000-4000-8000-000000000201',repeat('a',64))->>'status','claimed','Matching receipt claims cleanup');
select is(public.claim_account_deletion('de1e7200-0000-4000-8000-000000000201',repeat('a',64))->>'status','pending','Concurrent workers respect the lease');
reset role;
select throws_ok(format('select account_private.finish_deletion(%L,%L)',id,lease_id),'55000',null,'Completion cannot be claimed before Auth cleanup') from account_private.deletions where profile_id='de1e7200-0000-4000-8000-000000000001';
select * from finish();
rollback;
